    title: 'Расчет допусков и износа при восстановлении червячных пар и корпусных деталей машин',
    category: 'Услуги',
    summary: 'Инженерная методика определения первоначальных чертежных размеров по изношенным образцам с учетом стандартных рядов модулей и посадок по ГОСТ.',
    content: `При обратном инжиниринге изношенных деталей (зубчатые колеса, валы, корпуса насосов) нельзя использовать чистые сканированные размеры без анализа:
1. Выявление теоретических баз: восстановление центральных осей вращения и торцевых базирующих плоскостей по неистертым участкам.
2. Округление к нормальным рядам: измеренный межцентровый шаг или диаметр посадки под подшипник сопоставляется со стандартами ГОСТ 6636-69 и таблицами допусков (h6, k6, H7, F8).
3. Анализ пятна контакта: для червячных передач моделируется обкатка зубьев в CAD с коррекцией угла подъема линии витка.`,
    tags: ['Реверс-инжиниринг', 'Допуски и посадки', 'ГОСТ', 'Зубчатые передачи', 'Инжиниринг'],
